// Content models parsed from assets/data/content.json (generated by scripts/generate-content.ts).

List<String> _strings(dynamic v) =>
    (v as List? ?? const []).map((e) => e.toString()).toList();

class SessionItem {
  final String e;
  final int s;

  /// Lesson phase label ("Warm-up", "New today", …) — authored courses only.
  final String? p;

  /// Breath-paced flow this movement belongs to ([YogaFlow]), its round (1-based) and spoken cue.
  final String? f;
  final int? r;
  final String? c;

  /// Flow moves filmed as real movement: the transition film into this shape (`yt-…`), played once.
  final String? v;

  /// True when the pose's own hold film continues after the transition; otherwise its last frame stays.
  final bool vl;
  const SessionItem(
    this.e,
    this.s, [
    this.p,
    this.f,
    this.r,
    this.c,
    this.v,
    this.vl = false,
  ]);
  factory SessionItem.fromJson(Map<String, dynamic> j) => SessionItem(
    j['e'] as String,
    (j['s'] as num).toInt(),
    j['p'] as String?,
    j['f'] as String?,
    (j['r'] as num?)?.toInt(),
    j['c'] as String?,
    j['v'] as String?,
    (j['vl'] as num? ?? 0) == 1,
  );
}

/// A breath-paced Sun / Moon Salutation: one movement per breath, demonstrated once as a
/// sequence film (web `Flow`).
class YogaFlow {
  final String id, name, watch, go;
  final String? sanskrit;

  /// Sequence film key (`assets/video/<demo>.mp4`), or null.
  final String? demo;

  /// Exercise ids of one round, in order.
  final List<String> moves;
  YogaFlow.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      name = j['name'],
      watch = j['watch'] as String? ?? '',
      go = j['go'] as String? ?? '',
      sanskrit = j['sanskrit'] as String?,
      demo = j['demo'] as String?,
      moves = _strings(j['moves']);
}

List<SessionItem> _items(dynamic v) => (v as List)
    .map((e) => SessionItem.fromJson(e as Map<String, dynamic>))
    .toList();

class Exercise {
  final String id,
      name,
      category,
      kind,
      image,
      level,
      equipment,
      description,
      breath,
      cue;
  final int durationSec;
  final double kcalPerMin;
  final List<String> focus, steps, benefits;

  /// Optional licensed media (video loop / narrated guidance). Empty until provided.
  final String? video, audio;

  /// Key of our bundled demo film (`assets/video/<demo>.mp4`), or null.
  final String? demo;

  /// The tutor moving into the pose from a neutral start (`ye-…`), played once before [demo]
  /// loops; or null.
  final String? entry;
  final String? tip;

  /// Spoken while the tutor demonstrates the pose ("watch first").
  final String watch;

  /// Classical Sanskrit name (e.g. Vrksasana), when the pose has one.
  final String? sanskrit;
  bool get isAffirmation => kind == 'affirmation';

  /// Display name without the side suffix ("Tree Pose · Right" → "Tree Pose").
  String get baseName => name.split(' · ').first;

  /// Looping demo film: licensed network media first, then our bundled demo asset.
  ({String src, bool asset})? get film => video != null
      ? (src: video!, asset: false)
      : (demo != null ? (src: 'assets/video/$demo.mp4', asset: true) : null);
  Exercise.fromJson(Map<String, dynamic> j)
    : id = j['id'],
      name = j['name'],
      category = j['category'],
      kind = j['kind'] ?? 'move',
      video = (j['media'] as Map?)?['video'] as String?,
      audio = (j['media'] as Map?)?['audio'] as String?,
      demo = j['demo'] as String?,
      entry = j['entry'] as String?,
      tip = j['tip'] as String?,
      watch = j['watch'] as String? ?? '',
      sanskrit = j['sanskrit'] as String?,
      image = j['image'],
      level = j['level'],
      equipment = j['equipment'],
      description = j['description'],
      breath = j['breath'],
      cue = j['cue'],
      durationSec = (j['durationSec'] as num).toInt(),
      kcalPerMin = (j['kcalPerMin'] as num).toDouble(),
      focus = _strings(j['focus']),
      steps = _strings(j['steps']),
      benefits = _strings(j['benefits']);
}

class Category {
